/* Applies public prompt fields only after an explicit click. No essay transmission. */
var WritingSourceCore=(()=>{
 const names=['prompt','applicationContext','requirements','limit'];
 function fields(row){return{prompt:row.prompt,applicationContext:row.institution+' · '+row.route+' · '+row.section+' · Public page checked '+row.checked+'; confirm your cycle.',requirements:row.requirements.join('\n'),limit:row.maxWords==null?'':String(row.maxWords)}}
 function matches(row,input){const expected=fields(row);return names.every(k=>String(input[k]??'')===expected[k])}
 function words(text){return String(text||'').trim().split(/\s+/).filter(Boolean).length}
 function lengthPolicy(row){if(row.formatPolicy)return row.formatPolicy;if(row.maxWords!=null)return row.minWords!=null?row.minWords+'–'+row.maxWords+' words required':'Maximum '+row.maxWords+' words; no published minimum.';return row.suggestedWords?'Suggested '+row.suggestedWords.join('–')+' words; no hard maximum stated on this source page.':'Confirm the word policy in your application portal.'}
 function assess(row,text){const count=words(text),messages=[];if(row.optional)messages.push('Optional section: you may leave it out.');if(row.optional&&!count)return{count,messages};if(row.minWords!=null&&count<row.minWords)messages.push('Below the published minimum of '+row.minWords+' words.');if(row.maxWords!=null&&count>row.maxWords)messages.push('Above the published maximum of '+row.maxWords+' words.');else if(row.maxWords!=null&&(row.minWords==null||count>=row.minWords))messages.push(row.minWords==null?'Within the published maximum. No minimum is stated.':'Within the published length range.');if(row.formatPolicy)messages.push(row.formatPolicy+' Check formatting in the final document; Camino cannot verify it.');if(row.suggestedWords){messages.push('Suggested length: '+row.suggestedWords[0]+'–'+row.suggestedWords[1]+' words.');messages.push('No hard maximum is stated on this source page; confirm the portal limit.')}return{count,messages}}
 return{fields,matches,assess,words,lengthPolicy};
})();
function publishedWritingTools(){return `<section class="writing-source-tools" aria-labelledby="writing-source-title"><h3 id="writing-source-title">Start with published writing instructions</h3><p>UW Seattle and UW Bothell college applications. General transfer prompts do not cover programs with separate prompts; check the scope below. Major-specific applications and other colleges need their own confirmed instructions.</p><label for="writing-source-choice">Choose a published prompt<select id="writing-source-choice"><option value="">Keep my own instructions</option>${PublishedWritingPrompts.map(row=>`<option value="${esc(row.id)}">${esc(row.institution+' · '+row.route+' · '+row.label)}</option>`).join('')}</select></label><div id="writing-source-preview"></div><button class="btn" id="apply-writing-source" type="button" disabled>Use instructions — replace prompt fields</button><p class="quiet-note">Replaces the prompt, application context, requirement notes and word-limit field. Your essay and activities stay in the editor. Nothing is saved or sent automatically.</p><p id="writing-source-status" role="status" aria-live="polite"></p></section>`}
function bindWritingSources(){const select=document.querySelector('#writing-source-choice'),form=document.querySelector('#essay-review');if(!select||!form)return;const button=document.querySelector('#apply-writing-source'),preview=document.querySelector('#writing-source-preview'),status=document.querySelector('#writing-source-status'),input=()=>Object.fromEntries(['prompt','applicationContext','requirements','limit'].map(k=>[k,String(form.elements.namedItem(k)?.value||'')]));const restored=PublishedWritingPrompts.find(row=>WritingSourceCore.matches(row,input()));if(restored)select.value=restored.id;const meter=()=>{const row=PublishedWritingPrompts.find(r=>r.id===select.value);let message='';if(row){if(WritingSourceCore.matches(row,input())){const r=WritingSourceCore.assess(row,form.elements.namedItem('essay').value);message='Approximate word count: '+r.count+'. '+r.messages.join(' ')+' The application portal counter is authoritative.'}else message='These published instructions are not currently applied, or the prompt fields were edited. Confirm the instructions before reviewing.'}if(status.textContent!==message)status.textContent=message};const draw=()=>{const row=PublishedWritingPrompts.find(r=>r.id===select.value);button.disabled=!row;preview.innerHTML=row?`<p><strong>${esc(row.section)}</strong> · Public source checked ${esc(row.checked)}</p><p>${esc(row.scope)}</p><p>${esc(WritingSourceCore.lengthPolicy(row))}</p><a class="journey-secondary" href="${esc(ProductCore.safeURL(row.source))}" target="_blank" rel="noopener">Published instructions</a><details><summary>Preview the published prompt text</summary><div class="catalog-source-excerpt" tabindex="0" aria-label="Published prompt text">${esc(row.prompt)}</div></details>`:'';meter()};select.onchange=draw;button.onclick=()=>{const row=PublishedWritingPrompts.find(r=>r.id===select.value);if(!row)return;if(WritingSourceCore.matches(row,input())){meter();return}for(const[k,v]of Object.entries(WritingSourceCore.fields(row)))form.elements.namedItem(k).value=v;form.dispatchEvent(new Event('input',{bubbles:true}));meter();toast('Published instructions loaded. Your draft has not been saved or sent.')};form.addEventListener('input',meter);form.addEventListener('camino:writing-restored',()=>{select.value=PublishedWritingPrompts.find(row=>WritingSourceCore.matches(row,input()))?.id||'';draw()});document.querySelector('#clear-application-draft')?.addEventListener('click',()=>{select.value='';draw()});draw()}
function installWritingSources(){const page=advisingPage;advisingPage=()=>page().replace('<form id="essay-review">','<form id="essay-review">'+publishedWritingTools());const oldBind=bind;bind=()=>{oldBind();bindWritingSources()}}
if(typeof module!=='undefined')module.exports=WritingSourceCore;
